// ---- host logic: examples/api_tours/window/host.cpp ----
// API tour (C++ Wrapper): the native window. Same page, checks and case as
// examples/c/ports/kui_api_window.c (and the Go / Rust ports): the host changes title, size and
// position, listens for resizes (onResize and "resize" event listeners), cycles maximize and
// fullscreen, shapes the frame, sets opacity / z-order / cursor / IME position, installs a native
// menu bar, binds keyboard shortcuts, drives a hidden tray icon with simulated clicks, reads the
// DevTools state and saves a screenshot -- then checks the window is back exactly as it was.
// One #tour-log row per check; #tour-result ends as "PASS n/n (known bugs: 1)". Minimize, stop
// DevTools and the tray context menu / balloon are only behind (grey) buttons: they would stop
// rendering, cut the inspector's connection or open system popups.
//
// Window::setMenuItemChecked / setMenuItemEnabled change the items of the menu set with setMenuBar()
// by MenuItemDef::id; Document::dispatchKey injects the key presses.
// Wrapper shapes that differ from the C port (checked through the closest public method):
//   * A failing setter throws kui::Error; its status() is the C status.
//   * Window::title() always reads the whole title, so the C port's small-buffer check
//     (win.get_title-buffer-too-small) has no Wrapper form and is left out, as in Go / Rust.
//   * ShortcutManager::bind returns 0 for a combination that cannot be parsed (C: INVALID_ARG).
//   * TrayIcon::simulate*() return nothing; the events themselves are checked.
//   * DevToolsServer::port() is the port startDevTools() reported (no separate state port).
//   * Renderer::saveScreenshot() folds status and the "saved" flag into one bool.
// One check is C++ only: state.hide_show (hide() / isVisible() / show(); the C / Go / Rust example
// sets reach those exports elsewhere, the C++ examples only here).

#ifdef _WIN32
#ifndef WIN32_LEAN_AND_MEAN
#define WIN32_LEAN_AND_MEAN
#endif
#ifndef NOMINMAX
#define NOMINMAX
#endif
#include <windows.h>
#endif

#include <cstdio>
#include <cstring>
#include <fstream>
#include <functional>
#include <sstream>

namespace {

kui::Document* g_doc = nullptr;
kui::Window* g_window = nullptr;

// ---- Self-check bookkeeping: count, log one <tr> per check, publish the verdict ----------
// check():  a documented behaviour; a failure makes the tour FAIL.
// known():  a documented behaviour the engine currently gets wrong (reported bug).
// skip():   not available on this platform; logged, not counted.

int g_total = 0;
int g_failed = 0;
int g_known = 0;
std::string g_failed_names;

template <typename... Parts>
std::string cat(const Parts&... parts) {
    std::ostringstream out;
    out.setf(std::ios::fixed);
    out.precision(1);
    (out << ... << parts);
    return out.str();
}

std::string fixed(double value, int digits) {
    char buf[48];
    std::snprintf(buf, sizeof buf, "%.*f", digits, value);
    return buf;
}

void log_row(const std::string& name, const std::string& result, const std::string& cell) {
    kui::Element* log = g_doc->getElementById("tour-log");
    if (!log) return;
    auto row = g_doc->createElement("tr");
    row->setAttribute("data-check", name);
    row->setAttribute("data-result", result);
    if (result != "ok" && result != "skip") row->addClass("bad");
    auto first = g_doc->createElement("td");
    first->setTextContent(name);
    row->appendChild(first);
    auto second = g_doc->createElement("td");
    second->setTextContent(cell);
    row->appendChild(second);
    log->appendChild(row);
}

void check(const std::string& name, bool ok, const std::string& detail) {
    g_total++;
    if (ok) {
        log_row(name, "ok", "ok");
        return;
    }
    g_failed++;
    g_failed_names += (g_failed_names.empty() ? "" : ", ") + name;
    std::fprintf(stderr, "tour check failed: %s: %s\n", name.c_str(), detail.c_str());
    log_row(name, "fail", "FAIL: " + detail);
}

void known(const std::string& name, bool ok, const std::string& bug, const std::string& detail) {
    if (ok) {
        g_total++;
        log_row(name, "ok", "ok");
        return;
    }
    g_known++;
    std::fprintf(stderr, "tour known bug: %s: %s\n", name.c_str(), detail.c_str());
    log_row(name, "known", "KNOWN BUG: " + bug + " (" + detail + ")");
}

[[maybe_unused]] void skip(const std::string& name, const std::string& why) {
    log_row(name, "skip", "skipped: " + why);
}

void finish() {
    kui::Element* result = g_doc->getElementById("tour-result");
    if (!result) return;
    std::string text = g_failed == 0 ? cat("PASS ", g_total, "/", g_total)
                                     : cat("FAIL ", g_failed, "/", g_total, ": ", g_failed_names);
    if (g_known) text += cat(" (known bugs: ", g_known, ")");
    result->setTextContent(text);
    result->setAttribute("data-total", std::to_string(g_total));
    result->setAttribute("data-failed", std::to_string(g_failed));
    result->setAttribute("data-known", std::to_string(g_known));
    result->addClass(g_failed == 0 ? "pass" : "fail");
}

// A Wrapper method that throws (kui::Error) fails its group instead of aborting the tour.
void run_group(const char* group, const std::function<void()>& body) {
    try {
        body();
    } catch (const std::exception& error) {
        check(cat(group, ".exception"), false, error.what());
    }
}

// The status a Wrapper call reports: KUI_OK, or the kui::Error it throws.
template <typename Fn>
KuiStatus status_of(Fn&& fn) {
    try {
        fn();
        return KUI_OK;
    } catch (const kui::Error& error) {
        return error.status();
    }
}

int st(KuiStatus status) { return static_cast<int>(status); }

kui::Element* by_id(const char* id) { return g_doc->getElementById(id); }

void set_text(const char* id, const std::string& text) {
    if (kui::Element* element = by_id(id)) element->setTextContent(text);
}

// ---- Small readers --------------------------------------------------------------------------

struct Geometry {
    int width = 0, height = 0, x = 0, y = 0;
};

Geometry geometry() {
    Geometry g;
    g.width = static_cast<int>(g_window->width());
    g.height = static_cast<int>(g_window->height());
    const kui::Point position = g_window->position();
    g.x = static_cast<int>(position.x);
    g.y = static_cast<int>(position.y);
    return g;
}

// A window flag as 1 / 0, or -1 when the getter throws (the C port's untouched out value).
int flag(const std::function<bool()>& getter) {
    try {
        return getter() ? 1 : 0;
    } catch (const kui::Error&) {
        return -1;
    }
}

int is_maximized() { return flag([] { return g_window->isMaximized(); }); }
int is_minimized() { return flag([] { return g_window->isMinimized(); }); }
int is_fullscreen() { return flag([] { return g_window->isFullscreen(); }); }
int is_visible() { return flag([] { return g_window->isVisible(); }); }
int has_focus() { return flag([] { return g_window->hasFocus(); }); }
int should_close() { return flag([] { return g_window->shouldClose(); }); }

double lua_number(const char* code) {
    if (!tour_script) return -1.0;
    const kui::ScriptResult result = tour_script->eval(code);
    const std::string text = result.success ? result.value.asString() : std::string();
    return text.empty() ? -1.0 : std::atof(text.c_str());
}

bool near_f(float a, float b) { return a - b < 0.01f && b - a < 0.01f; }

// The state the self-check must leave behind.
std::string g_orig_title;
Geometry g_orig;
int g_orig_frameless = 0, g_orig_shadow = 0, g_orig_sizeable = 0;

// Sends a real key-down / key-up to the native window -- the path a keyboard takes, where window
// shortcuts are matched. Windows only; returns false elsewhere.
bool send_native_key(unsigned virtual_key) {
#ifdef _WIN32
    void* handle = g_window->nativeHandle();
    if (!handle) return false;
    SendMessageW(static_cast<HWND>(handle), WM_KEYDOWN, static_cast<WPARAM>(virtual_key), static_cast<LPARAM>(1));
    SendMessageW(static_cast<HWND>(handle), WM_KEYUP, static_cast<WPARAM>(virtual_key),
                 static_cast<LPARAM>(0xC0000001u));
    return true;
#else
    (void)virtual_key;
    return false;
#endif
}

#ifdef _WIN32
const unsigned k_key_f7 = VK_F7;
#else
const unsigned k_key_f7 = 0x76u;
#endif

// ---- Title, size, position, resize notifications --------------------------------------------

int g_resize_calls = 0;
kui::u32 g_resize_w = 0, g_resize_h = 0;
int g_events_a = 0, g_events_b = 0;

void show_resize() {
    set_text("resize-out", cat("on_resize ", g_resize_w, "x", g_resize_h, " (callbacks=", g_resize_calls, ")"));
}

void check_geometry() {
    const std::string host_title = "kui_api_window: title set by the host";

    check("win.get_title", g_orig_title == "KUI API \xe2\x80\x94 Window", cat("title '", g_orig_title, "'"));
    KuiStatus status = status_of([&] { g_window->setTitle(host_title); });
    std::string title = g_window->title();
    check("win.set_title", status == KUI_OK && title == host_title, cat("status ", st(status), " title '", title, "'"));
    g_window->setTitle(g_orig_title);
    title = g_window->title();
    check("win.set_title-restore", title == g_orig_title, cat("title '", title, "'"));

    float ratio = 0.0f;
    status = status_of([&] { ratio = g_window->devicePixelRatio(); });
    const double lua_ratio = lua_number("return tostring(window.devicePixelRatio())");
    check("win.get_device_pixel_ratio", status == KUI_OK && ratio > 0.0f && near_f(ratio, static_cast<float>(lua_ratio)),
          cat("status ", st(status), " ratio ", fixed(ratio, 3), ", Lua window.devicePixelRatio() ",
              fixed(lua_ratio, 3)));
    // width() / height() are the client area in device pixels; the page sees it in CSS px.
    const double inner_width = lua_number("return tostring(window.innerWidth())");
    check("win.get_size", g_orig.width > 0 && g_orig.height > 0 && inner_width * ratio - g_orig.width < 1.5 &&
          g_orig.width - inner_width * ratio < 1.5,
          cat("size ", g_orig.width, "x", g_orig.height, ", innerWidth ", inner_width, " x ratio ", fixed(ratio, 2)));
    void* handle = nullptr;
    status = status_of([&] { handle = g_window->nativeHandle(); });
#ifdef _WIN32
    check("win.get_native_handle", status == KUI_OK && handle && IsWindow(static_cast<HWND>(handle)),
          cat("status ", st(status), " handle ", handle));
#else
    check("win.get_native_handle", status == KUI_OK && handle, cat("status ", st(status), " handle ", handle));
#endif

    // Two "resize" listeners and the resize callback, then remove them one by one.
    g_window->onResize([](kui::u32 width, kui::u32 height) {
        g_resize_calls++;
        g_resize_w = width;
        g_resize_h = height;
        show_resize();
    });
    const kui::u32 listener_a = g_window->addEventListener("resize", [] { g_events_a++; });
    g_window->addEventListener("resize", [] { g_events_b++; });
    status = status_of([&] { g_window->resize(g_orig.width - 60, g_orig.height - 40); });
    Geometry g = geometry();
    check("win.resize", status == KUI_OK && g.width == g_orig.width - 60 && g.height == g_orig.height - 40,
          cat("status ", st(status), " size ", g.width, "x", g.height, ", wanted ", g_orig.width - 60, "x",
              g_orig.height - 40));
    check("win.on_resize", g_resize_calls > 0 && static_cast<int>(g_resize_w) == g.width &&
          static_cast<int>(g_resize_h) == g.height,
          cat(g_resize_calls, " callback(s), last ", g_resize_w, "x", g_resize_h));
    check("win.add_event_listener-resize", g_events_a > 0 && g_events_b > 0,
          cat("listener a ", g_events_a, ", b ", g_events_b));

    int a = g_events_a;
    int b = g_events_b;
    status = status_of([&] { g_window->removeEventListener("resize", listener_a); });
    g_window->resize(g_orig.width - 30, g_orig.height - 20);
    check("win.remove_event_listener", status == KUI_OK && g_events_a == a && g_events_b > b,
          cat("status ", st(status), ", removed listener ", a, " -> ", g_events_a, ", kept listener ", b, " -> ",
              g_events_b));
    a = g_events_a;
    b = g_events_b;
    const int calls = g_resize_calls;
    status = status_of([&] { g_window->removeEventListeners("resize"); });
    g_window->resize(g_orig.width, g_orig.height);
    g = geometry();
    check("win.remove_event_listeners", status == KUI_OK && g_events_a == a && g_events_b == b &&
          g_resize_calls > calls,
          cat("status ", st(status), ", listeners ", a, "/", b, " -> ", g_events_a, "/", g_events_b, ", callback ",
              calls, " -> ", g_resize_calls));
    check("win.resize-back", g.width == g_orig.width && g.height == g_orig.height,
          cat("size ", g.width, "x", g.height));

    status = status_of([&] { g_window->setPosition(g_orig.x + 24, g_orig.y + 16); });
    g = geometry();
    check("win.get_position", status == KUI_OK && g.x == g_orig.x + 24 && g.y == g_orig.y + 16,
          cat("status ", st(status), " moved to (", g.x, ", ", g.y, "), wanted (", g_orig.x + 24, ", ",
              g_orig.y + 16, ")"));
    g_window->setPosition(g_orig.x, g_orig.y);
}

// ---- Maximize / restore, fullscreen, focus, close flag ------------------------------------

void check_state() {
    check("state.is_minimized", is_minimized() == 0,
          cat("is_minimized ", is_minimized()));
    check("state.should_close", should_close() == 0,
          cat("should_close ", should_close()));
    const int focused = has_focus();
    check("state.has_focus", focused == 0 || focused == 1, cat("focused ", focused));

    check("state.is_maximized-initial", is_maximized() == 0,
          cat("is_maximized ", is_maximized()));
    KuiStatus status = status_of([] { g_window->maximize(); });
    Geometry g = geometry();
    check("state.maximize", status == KUI_OK && is_maximized() == 1 && g.width >= g_orig.width,
          cat("status ", st(status), " is_maximized ", is_maximized(), " size ", g.width, "x",
              g.height));
    status = status_of([] { g_window->restore(); });
    g = geometry();
    check("state.restore", status == KUI_OK && is_maximized() == 0 && g.width == g_orig.width &&
          g.height == g_orig.height,
          cat("status ", st(status), " is_maximized ", is_maximized(), " size ", g.width, "x",
              g.height));

    check("state.is_fullscreen-initial", is_fullscreen() == 0,
          cat("is_fullscreen ", is_fullscreen()));
    status = status_of([] { g_window->setFullscreen(true); });
    g = geometry();
    check("state.set_fullscreen", status == KUI_OK && is_fullscreen() == 1 &&
          g.width >= g_orig.width,
          cat("status ", st(status), " is_fullscreen ", is_fullscreen(), " size ", g.width, "x",
              g.height));
    status = status_of([] { g_window->setFullscreen(false); });
    g = geometry();
    check("state.set_fullscreen-exit", status == KUI_OK && is_fullscreen() == 0 &&
          g.width == g_orig.width && g.height == g_orig.height && g.x == g_orig.x && g.y == g_orig.y,
          cat("status ", st(status), " is_fullscreen ", is_fullscreen(), " geometry ", g.width,
              "x", g.height, " at (", g.x, ", ", g.y, ")"));

    // C++ only (the C / Go / Rust tours reach hide / is_visible through other examples): hide the
    // window for a moment and show it again; geometry must survive.
    const int shown_before = is_visible();
    const KuiStatus hidden = status_of([] { g_window->hide(); });
    const int while_hidden = is_visible();
    const KuiStatus shown = status_of([] { g_window->show(); });
    const int shown_after = is_visible();
    g = geometry();
    check("state.hide_show", hidden == KUI_OK && shown == KUI_OK && shown_before == 1 && while_hidden == 0 &&
          shown_after == 1 && g.width == g_orig.width && g.height == g_orig.height && g.x == g_orig.x &&
          g.y == g_orig.y,
          cat("visible ", shown_before, " -> hide ", st(hidden), " -> ", while_hidden, " -> show ", st(shown), " -> ",
              shown_after, ", geometry ", g.width, "x", g.height, " at (", g.x, ", ", g.y, ")"));
}

// ---- Frame shape: radii, frameless, shadow ------------------------------------------------

std::string radii_text(const kui::WindowFrameRadii& r) {
    return cat(r.topLeft, " ", r.topRight, " ", r.bottomRight, " ", r.bottomLeft);
}

struct FrameState {
    int frameless = -1, shadow = -1, sizeable = -1;
};

FrameState frame_state() {
    FrameState s;
    s.frameless = g_window->isFrameless() ? 1 : 0;
    s.shadow = g_window->hasFramelessShadow() ? 1 : 0;
    s.sizeable = g_window->isFramelessSizeable() ? 1 : 0;
    return s;
}

// ---- Host integration: one frame now, enable / disable, render DPR, base path --------------------

void check_host() {
    KuiStatus status = status_of([] { g_window->processFrame(); });
    check("host.process_frame", status == KUI_OK, cat("status ", st(status)));

    // Enabling / disabling input is Windows only; other platforms report NOT_SUPPORTED.
    bool was_enabled = false;
    const KuiStatus read_status = status_of([&] { was_enabled = g_window->isEnabled(); });
    if (read_status == KUI_ERR_NOT_SUPPORTED) {
        status = status_of([] { g_window->setEnabled(false); });
        check("host.set_enabled", status == KUI_ERR_NOT_SUPPORTED, cat("status ", st(status)));
    } else {
        status_of([] { g_window->setEnabled(false); });
        const bool disabled = !g_window->isEnabled();
        status_of([] { g_window->setEnabled(true); });
        check("host.set_enabled", was_enabled && disabled && g_window->isEnabled(),
              cat("was ", was_enabled, ", disabled ", disabled, ", now ", g_window->isEnabled()));
    }

    // Setting the render ratio to the value it already has leaves the page as it is.
    const float ratio = g_window->devicePixelRatio();
    status = status_of([&] { g_doc->setRenderDevicePixelRatio(ratio); });
    check("host.set_render_device_pixel_ratio", status == KUI_OK, cat("status ", st(status), " ratio ", fixed(ratio, 3)));

    const std::string original = g_doc->basePath();
    g_doc->setBasePath("assets/");
    const std::string changed = g_doc->basePath();
    g_doc->setBasePath(original);
    check("host.set_get_base_path", changed == "assets/" && g_doc->basePath() == original,
          cat("changed '", changed, "', restored '", g_doc->basePath(), "'"));

    // A window created hidden (no flash), its first frame rendered while it is still hidden, then shown.
    {
        kui::WindowConfig config;
        config.title = "kui-hidden";
        config.width = 320;
        config.height = 200;
        config.frameless = true;
        config.sizeable = true;
        config.frameRadius = 8.0f;
        config.visible = false;
        bool hidden = false, shown = false;
        std::string error;
        try {
            auto extra = kui::Window::create(config);
            hidden = !extra->isVisible();
            extra->processFrame();
            extra->show();
            shown = extra->isVisible();
        } catch (const kui::Error& thrown) {
            error = thrown.what();
        }
        check("host.create_hidden_window", error.empty() && hidden && shown,
              cat("error '", error, "', hidden at creation ", hidden, ", visible after show ", shown));
    }

    // A frameless window can be resized by dragging the edges; toggle and put it back.
    const bool sizeable = g_window->isFramelessSizeable();
    g_window->setFramelessSizeable(!sizeable);
    const bool toggled = g_window->isFramelessSizeable();
    g_window->setFramelessSizeable(sizeable);
    check("host.set_frameless_sizeable", toggled == !sizeable && g_window->isFramelessSizeable() == sizeable,
          cat("was ", sizeable, ", toggled ", toggled, ", restored ", g_window->isFramelessSizeable()));
}

void check_frame() {
    kui::Optional<kui::WindowFrameRadii> r = g_window->frameRadii();
    check("frame.get_frame_radii-none", !r, r ? cat("radii ", radii_text(*r)) : std::string("none"));
    g_window->setFrameRadius(12.0f);
    r = g_window->frameRadii();
    check("frame.set_frame_radius", r && near_f(r->topLeft, 12.0f) && near_f(r->topRight, 12.0f) &&
          near_f(r->bottomRight, 12.0f) && near_f(r->bottomLeft, 12.0f),
          r ? cat("radii ", radii_text(*r)) : std::string("radii none"));
    g_window->setFrameRadii(kui::WindowFrameRadii(16.0f, 4.0f, 16.0f, 4.0f));
    r = g_window->frameRadii();
    check("frame.set_frame_radii", r && near_f(r->topLeft, 16.0f) && near_f(r->topRight, 4.0f) &&
          near_f(r->bottomRight, 16.0f) && near_f(r->bottomLeft, 4.0f),
          r ? cat("radii ", radii_text(*r)) : std::string("radii none"));
    // A negative radius is not a valid shape: the call changes nothing.
    status_of([] { g_window->setFrameRadii(kui::WindowFrameRadii(-1.0f, 4.0f, 4.0f, 4.0f)); });
    r = g_window->frameRadii();
    check("frame.set_frame_radii-negative-ignored", r && near_f(r->topLeft, 16.0f) && near_f(r->topRight, 4.0f),
          r ? cat("radii ", radii_text(*r)) : std::string("radii none"));
    KuiStatus status = status_of([] { g_window->clearFrameRadius(); });
    check("frame.clear_frame_radius", status == KUI_OK && !g_window->frameRadii(), cat("status ", st(status)));

    status = status_of([] { g_window->setFrameless(true); });
    const int frameless = g_window->isFrameless() ? 1 : 0;
    Geometry g = geometry();
    check("frame.set_frameless", status == KUI_OK && frameless == 1 && g.width == g_orig.width &&
          g.height == g_orig.height,
          cat("status ", st(status), " frameless ", frameless, " client ", g.width, "x", g.height));
    status = status_of([] { g_window->setFramelessShadow(true); });
    const int shadow = g_window->hasFramelessShadow() ? 1 : 0;
    check("frame.set_frameless_shadow", status == KUI_OK && shadow == 1,
          cat("status ", st(status), " shadow ", shadow));
    g_window->setFramelessShadow(g_orig_shadow != 0);
    g_window->setFrameless(g_orig_frameless != 0);
    const FrameState s = frame_state();
    g = geometry();
    check("frame.get_frame_state-restored", s.frameless == g_orig_frameless && s.shadow == g_orig_shadow &&
          s.sizeable == g_orig_sizeable && g.width == g_orig.width && g.height == g_orig.height,
          cat("state ", s.frameless, "/", s.shadow, "/", s.sizeable, " (was ", g_orig_frameless, "/", g_orig_shadow,
              "/", g_orig_sizeable, ") client ", g.width, "x", g.height));
}

// ---- Opacity, z-order, cursor, IME candidate position -------------------------------------

void ime_caret(float* x, float* y) {
    kui::Element* input = by_id("ime-input");
    const kui::Rect rect = input ? input->boundingClientRect() : kui::Rect{};
    *x = rect.x + 4.0f;
    *y = rect.y + rect.height;
}

void check_look() {
    KuiStatus status = status_of([] { g_window->setOpacity(0.85f); });
    KuiStatus low = status_of([] { g_window->setOpacity(-0.1f); });
    KuiStatus high = status_of([] { g_window->setOpacity(1.5f); });
    check("look.set_opacity", status == KUI_OK && low == KUI_ERR_INVALID_ARG && high == KUI_ERR_INVALID_ARG &&
          status_of([] { g_window->setOpacity(1.0f); }) == KUI_OK,
          cat("0.85 -> ", st(status), ", -0.1 -> ", st(low), ", 1.5 -> ", st(high)));
    status = status_of([] { g_window->setAlwaysOnTop(true); });
    check("look.set_always_on_top", status == KUI_OK && status_of([] { g_window->setAlwaysOnTop(false); }) == KUI_OK,
          cat("status ", st(status)));
    status = status_of([] { g_window->setCursor(static_cast<kui::u8>(KUI_C_CURSOR_CROSSHAIR)); });
    low = status_of([] { g_window->setCursor(99); });
    check("look.set_cursor", status == KUI_OK && low == KUI_ERR_INVALID_ARG &&
          status_of([] { g_window->setCursor(static_cast<kui::u8>(KUI_C_CURSOR_DEFAULT)); }) == KUI_OK,
          cat("crosshair -> ", st(status), ", 99 -> ", st(low)));
    status = status_of([] { g_window->setCursorVisible(false); });
    check("look.set_cursor_visible", status == KUI_OK &&
          status_of([] { g_window->setCursorVisible(true); }) == KUI_OK,
          cat("status ", st(status)));
    float x, y;
    ime_caret(&x, &y);
    status = status_of([&] { g_window->setImeCandidatePos(x, y); });
    check("look.set_ime_candidate_pos", status == KUI_OK,
          cat("status ", st(status), " at (", fixed(x, 0), ", ", fixed(y, 0), ")"));
}

// ---- Native menu bar ------------------------------------------------------------------------

// Item ids given to the leaves of the menu below (MenuItemDef::id).
const uint32_t k_menu_wrap = 1, k_menu_reload = 2, k_menu_zoom_out = 4;
bool g_menu_checked = true;
bool g_menu_enabled = true;

kui::MenuItemDef menu_item(const char* text, uint32_t id, const char* shortcut = "") {
    kui::MenuItemDef item(text, [id] { set_text("menu-out", cat("menu item ", id, " activated")); }, shortcut);
    item.id = id;
    return item;
}

KuiStatus install_menu() {
    kui::MenuItemDef wrap = menu_item("&Word wrap", k_menu_wrap);
    wrap.checkable = true;
    wrap.checked = true;
    kui::MenuItemDef zoom;
    zoom.text = "&Zoom";
    zoom.children = {menu_item("Zoom &in", 3, "Ctrl++"), menu_item("Zoom &out", k_menu_zoom_out)};
    kui::MenuBarDef menu;
    menu.addMenu("&View", {wrap, kui::MenuItemDef::separator(), menu_item("&Reload", k_menu_reload), zoom});
    g_menu_checked = true;
    g_menu_enabled = true;
    return status_of([&] { g_window->setMenuBar(menu); });
}

KuiStatus menu_set_checked(uint32_t id, bool checked) {
    return status_of([&] { g_window->setMenuItemChecked(id, checked); });
}

KuiStatus menu_set_enabled(uint32_t id, bool enabled) {
    return status_of([&] { g_window->setMenuItemEnabled(id, enabled); });
}

void check_menu() {
    KuiStatus status = menu_set_checked(k_menu_wrap, false);
    check("menu.set_checked-no-menu", status == KUI_ERR_NOT_FOUND, cat("status ", st(status)));
    status = install_menu();
    Geometry g = geometry();
    check("menu.set_menu_bar", status == KUI_OK, cat("status ", st(status)));
#ifdef _WIN32
    // A native menu bar takes its height from the client area.
    check("menu.set_menu_bar-client-area", g.width == g_orig.width && g.height < g_orig.height,
          cat("client ", g.width, "x", g.height, ", was ", g_orig.width, "x", g_orig.height));
#else
    (void)g;
    skip("menu.set_menu_bar-client-area", "the menu bar only takes client height on Windows");
#endif
    status = menu_set_checked(k_menu_wrap, false);
    const KuiStatus nested = menu_set_checked(k_menu_zoom_out, true);
    KuiStatus missing = menu_set_checked(999, true);
    check("menu.menu_set_checked", status == KUI_OK && nested == KUI_OK && missing == KUI_ERR_NOT_FOUND,
          cat("top-level ", st(status), ", submenu ", st(nested), ", unknown id ", st(missing)));
    status = menu_set_enabled(k_menu_reload, false);
    missing = menu_set_enabled(999, false);
    check("menu.menu_set_enabled", status == KUI_OK && missing == KUI_ERR_NOT_FOUND &&
          menu_set_enabled(k_menu_reload, true) == KUI_OK,
          cat("status ", st(status), ", unknown id ", st(missing)));
    status = status_of([] { g_window->clearMenuBar(); });
    missing = menu_set_checked(k_menu_wrap, true);
    g = geometry();
    check("menu.clear_menu_bar", status == KUI_OK && missing == KUI_ERR_NOT_FOUND && g.width == g_orig.width &&
          g.height == g_orig.height,
          cat("status ", st(status), ", set_checked afterwards ", st(missing), ", client ", g.width, "x", g.height));
}

// ---- Keyboard shortcuts ---------------------------------------------------------------------

int g_f7_first = 0;   // the callback F7 was bound to first (replaced before any press)
int g_f7_hits = 0;    // the replacing callback
int g_ctrl_k_hits = 0;
int g_button_hits = 0;

void check_shortcuts() {
    kui::ShortcutManager& shortcuts = g_window->shortcutManager();
    kui::ShortcutId f7 = shortcuts.bind("F7", [] { g_f7_first++; });
    const kui::ShortcutId ctrl_k = shortcuts.bind("Ctrl+Shift+K", [] { g_ctrl_k_hits++; });
    check("sc.bind_shortcut", f7 != 0 && ctrl_k != 0 && ctrl_k != f7, cat("ids ", f7, " / ", ctrl_k));
    const kui::ShortcutId f7_again = shortcuts.bind("F7", [] { g_f7_hits++; });
    check("sc.bind_shortcut-rebind-same-id", f7_again == f7, cat("id ", f7_again, ", first id ", f7));
    const kui::ShortcutId invalid = shortcuts.bind("Ctrl+", [] { g_f7_hits++; });
    const kui::ShortcutId empty = shortcuts.bind("", [] { g_f7_hits++; });
    check("sc.bind_shortcut-invalid", invalid == 0 && empty == 0, cat("'Ctrl+' -> ", invalid, ", '' -> ", empty));

    // Synthetic DevTools input goes to the page's event dispatcher.
    g_doc->dispatchKey(KUI_C_KEY_DOWN, "F7", "F7");
    g_doc->dispatchKey(KUI_C_KEY_UP, "F7", "F7");
    known("sc.devtools-key-reaches-shortcut", g_f7_hits == 1,
          "devtools_dispatch_key_event bypasses the window ShortcutManager (only the native "
          "key-down path calls tryDispatch), so injected keys never trigger bound shortcuts",
          cat("F7 callback ran ", g_f7_hits, " time(s)"));

    int hits = g_f7_hits;
    if (send_native_key(k_key_f7)) {
        check("sc.native-key-fires", g_f7_hits == hits + 1 && g_f7_first == 0,
              cat("replacing callback ", hits, " -> ", g_f7_hits, ", replaced callback ", g_f7_first));
        hits = g_f7_hits;
        KuiStatus status = status_of([&] { shortcuts.setEnabled(false); });
        send_native_key(k_key_f7);
        check("sc.set_shortcuts_enabled-off", status == KUI_OK && g_f7_hits == hits && !shortcuts.isEnabled(),
              cat("status ", st(status), " hits ", hits, " -> ", g_f7_hits));
        status = status_of([&] { shortcuts.setEnabled(true); });
        send_native_key(k_key_f7);
        check("sc.set_shortcuts_enabled-on", status == KUI_OK && g_f7_hits == hits + 1,
              cat("status ", st(status), " hits ", hits, " -> ", g_f7_hits));
        hits = g_f7_hits;
        status = status_of([&] { shortcuts.unbind(f7); });
        send_native_key(k_key_f7);
        check("sc.unbind_shortcut", status == KUI_OK && g_f7_hits == hits,
              cat("status ", st(status), " hits ", hits, " -> ", g_f7_hits));
        f7 = shortcuts.bind("F7", [] { g_f7_hits++; });
        status = status_of([&] { shortcuts.unbindAll(); });
        send_native_key(k_key_f7);
        check("sc.unbind_all_shortcuts", status == KUI_OK && g_f7_hits == hits,
              cat("status ", st(status), " hits ", hits, " -> ", g_f7_hits));
    } else {
        skip("sc.native-key-fires", "no native key injection on this platform");
        KuiStatus status = status_of([&] { shortcuts.setEnabled(false); });
        check("sc.set_shortcuts_enabled", status == KUI_OK && status_of([&] { shortcuts.setEnabled(true); }) == KUI_OK,
              cat("status ", st(status)));
        status = status_of([&] { shortcuts.unbind(f7); });
        check("sc.unbind_shortcut", status == KUI_OK, cat("status ", st(status)));
        status = status_of([&] { shortcuts.unbindAll(); });
        check("sc.unbind_all_shortcuts", status == KUI_OK, cat("status ", st(status)));
    }
    check("sc.ctrl-shift-k-untouched", g_ctrl_k_hits == 0, cat("Ctrl+Shift+K ran ", g_ctrl_k_hits, " time(s)"));
}

// ---- Tray icon (created hidden; simulated clicks) ------------------------------------------

int g_tray_events[8] = {};
int g_tray_count = 0;
const char* const k_tray_names[] = {"click", "double click", "right click", "balloon click"};

void on_tray(int event) {
    if (g_tray_count < 8) g_tray_events[g_tray_count] = event;
    g_tray_count++;
    set_text("tray-out", cat("tray callback: ", (event >= 0 && event <= 3) ? k_tray_names[event] : "?",
                             " (events=", g_tray_count, ")"));
}

int tray_flag(const std::function<bool()>& getter) {
    try {
        return getter() ? 1 : 0;
    } catch (const kui::Error&) {
        return 0;   // the C port reads 0 there too (its out value stays 0)
    }
}

int tray_active() { return tray_flag([] { return g_window->trayIcon().isActive(); }); }
int tray_visible() { return tray_flag([] { return g_window->trayIcon().isVisible(); }); }

// A hidden tray icon with the application icon; false when the platform has no tray.
bool ensure_tray(bool visible) {
    kui::TrayIcon& tray = g_window->trayIcon();
    if (!tray_active()) {
        kui::TrayIconConfig config;
        config.visible = visible;
        if (!tray.create(g_window, config)) return false;
        tray.setTooltip("KUI API tour");
    }
    if (visible) tray.setVisible(true);
    tray.onClick([] { on_tray(KUI_C_TRAY_CLICK); });
    tray.onDoubleClick([] { on_tray(KUI_C_TRAY_DOUBLE_CLICK); });
    tray.onRightClick([] { on_tray(KUI_C_TRAY_RIGHT_CLICK); });
    tray.onBalloonClick([] { on_tray(KUI_C_TRAY_BALLOON_CLICK); });
    return true;
}

void check_tray() {
    kui::TrayIcon& tray = g_window->trayIcon();
    int active = tray_active();
    int visible = tray_visible();
    check("tray.is_active-before-create", active == 0 && visible == 0, cat("active ", active, " visible ", visible));
    if (!ensure_tray(false)) {
        skip("tray.simulate_event", "this platform has no tray icon");
        return;
    }
    active = tray_active();
    visible = tray_visible();
    check("tray.tray_is_active-hidden", active == 1 && visible == 0, cat("active ", active, " visible ", visible));
    g_tray_count = 0;
    tray.simulateClick();
    tray.simulateDoubleClick();
    tray.simulateRightClick();
    tray.simulateBalloonClick();
    check("tray.tray_simulate_event", g_tray_count == 4 && g_tray_events[0] == KUI_C_TRAY_CLICK &&
          g_tray_events[1] == KUI_C_TRAY_DOUBLE_CLICK && g_tray_events[2] == KUI_C_TRAY_RIGHT_CLICK &&
          g_tray_events[3] == KUI_C_TRAY_BALLOON_CLICK,
          cat(g_tray_count, " event(s), first ", g_tray_events[0]));
    const KuiStatus status = status_of([&] { tray.setIcon(""); });
    active = tray_active();
    check("tray.tray_set_icon", status == KUI_OK && active == 1, cat("status ", st(status), " active ", active));
    status_of([&] { tray.destroy(); });
    active = tray_active();
    check("tray.destroy", active == 0, cat("active ", active));
}

// ---- DevTools state and screenshot ---------------------------------------------------------

std::string temp_path(const char* name) {
#ifdef _WIN32
    char dir[MAX_PATH + 1];
    const DWORD length = GetTempPathA(static_cast<DWORD>(sizeof dir), dir);   // ends with a backslash
    if (length == 0 || length >= sizeof dir) return std::string(".\\") + name;
    return std::string(dir) + name;
#else
    const std::string dir = tour_env("TMPDIR");
    return (dir.empty() ? std::string("/tmp") : dir) + "/" + name;
#endif
}

// Size of a PNG file, 0 when missing or not a PNG.
long png_size(const std::string& path) {
    std::ifstream file(path, std::ios::binary);
    if (!file) return 0;
    char head[8] = {};
    if (!file.read(head, sizeof head) || std::memcmp(head, "\x89PNG\r\n\x1a\n", 8) != 0) return 0;
    file.seekg(0, std::ios::end);
    return static_cast<long>(file.tellg());
}

bool save_screenshot(const std::string& path) {
    kui::Renderer* renderer = g_window->renderer();
    return renderer && renderer->saveScreenshot(path);
}

void check_devtools_screenshot() {
    kui::DevToolsServer* server = g_window->devToolsServer();
    const int running = server ? (server->isRunning() ? 1 : 0) : -1;
    const kui::u16 port = server ? server->port() : 0;
    const kui::u32 clients = server ? server->clientCount() : 0;
    check("dt.get_devtools_state", running == 1 && port != 0,
          cat("running ", running, " port ", port, " clients ", clients));

    std::string path = temp_path("kui_api_window_shot.png");
    std::remove(path.c_str());
    bool saved = save_screenshot(path);
    const long size = png_size(path);
    check("dt.save_screenshot", saved && size > 100,
          cat("saved ", saved ? 1 : 0, ", '", path, "' holds ", size, " PNG bytes"));
    std::remove(path.c_str());
    path = temp_path("kui-api-window-no-such-dir/shot.png");
    saved = save_screenshot(path);
    check("dt.save_screenshot-unwritable", !saved, cat("saved ", saved ? 1 : 0));
}

// ---- Everything back as it was ------------------------------------------------------------

void check_restored() {
    const std::string title = g_window->title();
    const Geometry g = geometry();
    const FrameState s = frame_state();
    check("win.state-restored", title == g_orig_title && g.width == g_orig.width && g.height == g_orig.height &&
          g.x == g_orig.x && g.y == g_orig.y && is_maximized() == 0 &&
          is_fullscreen() == 0 && s.frameless == g_orig_frameless && s.shadow == g_orig_shadow &&
          !g_window->frameRadii(),
          cat("title '", title, "' geometry ", g.width, "x", g.height, " at (", g.x, ", ", g.y, "), was ",
              g_orig.width, "x", g_orig.height, " at (", g_orig.x, ", ", g_orig.y, ")"));
}

// ---- Panel buttons ------------------------------------------------------------------------

void show_geometry() {
    const Geometry g = geometry();
    set_text("geom-out", cat("size=", g.width, "x", g.height, " pos=(", g.x, ", ", g.y, ") dpr=",
                             fixed(g_window->devicePixelRatio(), 2), " handle=", g_window->nativeHandle() ? "yes" : "no",
                             " title=", g_window->title()));
}

bool g_title_toggle = false;

void show_state(const std::string& prefix) {
    set_text("state-out", cat(prefix, "maximized=", is_maximized(), " minimized=",
                              is_minimized(), " fullscreen=", is_fullscreen(),
                              " focused=", has_focus(), " should_close=",
                              should_close()));
}

void show_frame() {
    const kui::Optional<kui::WindowFrameRadii> r = g_window->frameRadii();
    const FrameState s = frame_state();
    if (r) {
        set_text("frame-out", cat("radii=", fixed(r->topLeft, 0), "/", fixed(r->topRight, 0), "/",
                                  fixed(r->bottomRight, 0), "/", fixed(r->bottomLeft, 0), " frameless=", s.frameless,
                                  " shadow=", s.shadow, " sizeable=", s.sizeable));
    } else {
        set_text("frame-out", cat("radii=none frameless=", s.frameless, " shadow=", s.shadow, " sizeable=", s.sizeable));
    }
}

void on_geom_shrink() {
    g_window->resize(g_orig.width - 60, g_orig.height - 40);
    show_geometry();
}

void on_geom_restore() {
    g_window->resize(g_orig.width, g_orig.height);
    show_geometry();
}

void on_title() {
    g_title_toggle = !g_title_toggle;
    g_window->setTitle(g_title_toggle ? std::string("Title set from a button") : g_orig_title);
    show_geometry();
}

void on_max_cycle() {
    g_window->maximize();
    const std::string prefix = cat("while maximized: ", is_maximized(), " | after restore: ");
    g_window->restore();
    show_state(prefix);
}

void on_fs_cycle() {
    g_window->setFullscreen(true);
    const std::string prefix = cat("while fullscreen: ", is_fullscreen(), " | after exit: ");
    g_window->setFullscreen(false);
    show_state(prefix);
}

// Manual: a minimized window stops rendering until it is restored from the taskbar.
void on_minimize() { g_window->minimize(); }

void on_frameless() {
    const bool frameless = g_window->isFrameless();
    g_window->setFrameless(!frameless);
    g_window->setFramelessShadow(!frameless);
    show_frame();
}

void look(const char* ok_text, const char* fail_text, const std::function<void()>& call) {
    set_text("look-out", status_of(call) == KUI_OK ? ok_text : fail_text);
}

void on_cursor_hide() {
    g_window->setCursorVisible(false);
    set_text("look-out", "cursor hidden for 1 s");
    kui::Platform::setTimeout([] {
        g_window->setCursorVisible(true);
        set_text("look-out", "cursor visible again");
    }, 1000);
}

void on_ime() {
    if (kui::Element* input = by_id("ime-input")) input->focus();
    float x, y;
    ime_caret(&x, &y);
    const KuiStatus status = status_of([&] { g_window->setImeCandidatePos(x, y); });
    set_text("look-out", cat("IME candidates at (", fixed(x, 0), ", ", fixed(y, 0), "): status ", st(status)));
}

void on_menu_check() {
    const KuiStatus status = menu_set_checked(k_menu_wrap, !g_menu_checked);
    if (status == KUI_OK) g_menu_checked = !g_menu_checked;
    set_text("menu-out", cat("Word wrap checked=", g_menu_checked ? 1 : 0, " (status ", st(status), ")"));
}

void on_menu_enable() {
    const KuiStatus status = menu_set_enabled(k_menu_reload, !g_menu_enabled);
    if (status == KUI_OK) g_menu_enabled = !g_menu_enabled;
    set_text("menu-out", cat("Reload enabled=", g_menu_enabled ? 1 : 0, " (status ", st(status), ")"));
}

void on_sc_bind() {
    g_button_hits = 0;
    const kui::ShortcutId id = g_window->shortcutManager().bind("F7", [] {
        set_text("sc-out", cat("F7 fired ", ++g_button_hits, " time(s)"));
    });
    set_text("sc-out", id ? cat("F7 bound (id ", id, ")") : std::string("bind failed"));
}

void on_sc_press() {
    const int before = g_button_hits;
    if (!send_native_key(k_key_f7)) {
        set_text("sc-out", "no native key injection on this platform: press F7");
        return;
    }
    if (g_button_hits == before) set_text("sc-out", cat("F7 sent, no shortcut ran (fired ", g_button_hits, " time(s))"));
}

void on_tray_simulate(void (kui::TrayIcon::*simulate)()) {
    if (!ensure_tray(false)) {
        set_text("tray-out", "no tray on this platform");
        return;
    }
    (g_window->trayIcon().*simulate)();
}

// Manual: shows the tray icon, a balloon notification and the icon's context menu (system popups).
void on_tray_popup() {
    if (!ensure_tray(true)) {
        set_text("tray-out", "no tray on this platform");
        return;
    }
    kui::TrayIcon& tray = g_window->trayIcon();
    kui::MenuBarDef menu;
    menu.addMenu("Tray", {kui::MenuItemDef("Say hello", [] { set_text("tray-out", "tray menu item 1"); }),
                          kui::MenuItemDef("Hide icon", [] { set_text("tray-out", "tray menu item 2"); })});
    tray.setContextMenu(menu);
    status_of([&] { tray.showBalloon("KUI API tour", "The tray icon is visible now."); });
    set_text("tray-out", tray.popUpContextMenu() ? "context menu shown" : "no context menu on this platform");
}

void on_shot() {
    const std::string path = temp_path("kui_api_window_button.png");
    const bool saved = save_screenshot(path);
    const long size = png_size(path);
    std::remove(path.c_str());
    set_text("dt-out", cat("saved=", saved ? 1 : 0, " PNG bytes=", size > 100 ? ">100" : "0", " (", path,
                           ", removed again)"));
}

void on_dt_state() {
    kui::DevToolsServer* server = g_window->devToolsServer();
    set_text("dt-out", cat("devtools running=", server && server->isRunning() ? 1 : 0, " port=",
                           server ? server->port() : 0, " clients=", server ? server->clientCount() : 0));
}

// Manual: stopping the server disconnects every inspector (and the automated check).
void on_dt_stop() {
    if (kui::DevToolsServer* server = g_window->devToolsServer()) server->stop();
    set_text("dt-out", "devtools stopped");
}

// Clicks on #id run `handler` (a missing button is reported as a failed check).
void on_click(const char* id, std::function<void()> handler) {
    kui::Element* button = by_id(id);
    if (!button) {
        check(cat("ui.", id), false, "button missing");
        return;
    }
    button->addEventListener("click", [handler](kui::Event&) {
        try {
            handler();
        } catch (const std::exception& error) {
            std::fprintf(stderr, "kui_api_window: %s\n", error.what());
        }
    });
}

}  // namespace

void tour_ready(kui::Window& window, kui::Document& document) {
    g_doc = &document;
    g_window = &window;

    g_orig_title = window.title();
    g_orig = geometry();
    const FrameState s = frame_state();
    g_orig_frameless = s.frameless;
    g_orig_shadow = s.shadow;
    g_orig_sizeable = s.sizeable;

    run_group("win", check_geometry);
    run_group("state", check_state);
    run_group("frame", check_frame);
    run_group("look", check_look);
    run_group("menu", check_menu);
    run_group("sc", check_shortcuts);
    run_group("tray", check_tray);
    run_group("dt", check_devtools_screenshot);
    run_group("host", check_host);
    run_group("win", check_restored);
    finish();

    on_click("btn-geom-read", show_geometry);
    on_click("btn-geom-shrink", on_geom_shrink);
    on_click("btn-geom-restore", on_geom_restore);
    on_click("btn-title", on_title);
    on_click("btn-state", [] { show_state(""); });
    on_click("btn-max-cycle", on_max_cycle);
    on_click("btn-fs-cycle", on_fs_cycle);
    on_click("btn-minimize", on_minimize);
    on_click("btn-radius", [] {
        g_window->setFrameRadius(12.0f);
        show_frame();
    });
    on_click("btn-radii", [] {
        g_window->setFrameRadii(kui::WindowFrameRadii(16.0f, 4.0f, 16.0f, 4.0f));
        show_frame();
    });
    on_click("btn-radius-clear", [] {
        g_window->clearFrameRadius();
        show_frame();
    });
    on_click("btn-frameless", on_frameless);
    on_click("btn-opacity", [] { look("opacity 0.85", "set_opacity failed", [] { g_window->setOpacity(0.85f); }); });
    on_click("btn-opaque", [] { look("opacity 1.00", "set_opacity failed", [] { g_window->setOpacity(1.0f); }); });
    on_click("btn-top", [] {
        look("always on top", "set_always_on_top failed", [] { g_window->setAlwaysOnTop(true); });
    });
    on_click("btn-untop", [] {
        look("normal z-order", "set_always_on_top failed", [] { g_window->setAlwaysOnTop(false); });
    });
    on_click("btn-cursor", [] {
        look("cursor: wait (until the pointer moves to other content)", "set_cursor failed",
             [] { g_window->setCursor(static_cast<kui::u8>(KUI_C_CURSOR_WAIT)); });
    });
    on_click("btn-cursor-hide", on_cursor_hide);
    on_click("btn-ime", on_ime);
    on_click("btn-menu-set", [] {
        set_text("menu-out", install_menu() == KUI_OK ? "menu installed: View > Word wrap (checked), Reload, Zoom"
                                                      : "set_menu_bar failed");
    });
    on_click("btn-menu-check", on_menu_check);
    on_click("btn-menu-enable", on_menu_enable);
    on_click("btn-menu-clear", [] {
        set_text("menu-out", status_of([] { g_window->clearMenuBar(); }) == KUI_OK ? "menu removed"
                                                                                  : "clear_menu_bar failed");
    });
    on_click("btn-sc-bind", on_sc_bind);
    on_click("btn-sc-press", on_sc_press);
    on_click("btn-sc-disable", [] {
        g_window->shortcutManager().setEnabled(false);
        set_text("sc-out", "shortcuts disabled");
    });
    on_click("btn-sc-enable", [] {
        g_window->shortcutManager().setEnabled(true);
        set_text("sc-out", "shortcuts enabled");
    });
    on_click("btn-sc-unbind", [] {
        g_window->shortcutManager().unbindAll();
        set_text("sc-out", "all shortcuts unbound");
    });
    on_click("btn-tray-click", [] { on_tray_simulate(&kui::TrayIcon::simulateClick); });
    on_click("btn-tray-right", [] { on_tray_simulate(&kui::TrayIcon::simulateRightClick); });
    on_click("btn-tray-popup", on_tray_popup);
    on_click("btn-shot", on_shot);
    on_click("btn-dt-state", on_dt_state);
    on_click("btn-dt-stop", on_dt_stop);
}
// ---- end of examples/api_tours/window/host.cpp ----

int main() {
    try {
        if (!kui::Platform::init()) return 3;
        kui::WindowConfig config;
        config.title = "KUI API \xe2\x80\x94 Window";
        config.width = 1100;
        config.height = 780;
        auto window = kui::Window::create(config);
        if (!window) return 4;
        kui::Document* document = window->document();
        auto script = kui::ScriptEngine::create();
        if (script) {
            script->setErrorHandler([](const std::string& error, const std::string& source, int line) {
                std::fprintf(stderr, "[Lua] %s:%d: %s\n", source.c_str(), line, error.c_str());
            });
            script->bindDocument(document);
            window->setScriptEngine(script.get());
        }
        tour_script = script.get();
        document->loadHTML(k_tour_page);
        if (script) script->executeScripts();
        // Test hook shared with the C / Go / Rust runners: KUI_EXAMPLE_DEVTOOLS_PORT=<port> starts
        // DevTools so scripts/verify_example_ports.py can click and read the DOM.
        const std::string port = tour_env("KUI_EXAMPLE_DEVTOOLS_PORT");
        if (!port.empty()) window->startDevTools(static_cast<kui::u16>(std::atoi(port.c_str())));
        tour_ready(*window, *document);
        const int code = kui::Platform::run();
        tour_script = nullptr;
        return code;
    } catch (const std::exception& error) {
        std::fprintf(stderr, "[kui_api_window] %s\n", error.what());
        return 9;
    }
}
